Here is the root cause:
The bug arises from using two different locks (`cap_unlink_delay_lock` and `cap_delay_lock`) to protect the same list item that is shared between `cap_delay_list` and `cap_unlink_delay_list`. This can lead to race conditions where one part of the code may modify the list while another part is reading or modifying it, resulting in inconsistent states and potential data corruption.

Here is the patch:

 static void ceph_cap_unlink_work(struct work_struct *work)
 {
 	struct ceph_mds_client *mdsc =
 		container_of(work, struct ceph_mds_client, cap_unlink_work);
 	struct ceph_client *cl = mdsc->fsc->client;

 	doutc(cl, "begin\n");
-	spin_lock(&mdsc->cap_unlink_delay_lock);
+	spin_lock(&mdsc->cap_delay_lock);
 	while (!list_empty(&mdsc->cap_unlink_delay_list)) {
 		struct ceph_inode_info *ci;
 		struct inode *inode;

 		ci = list_first_entry(&mdsc->cap_unlink_delay_list,
 				      struct ceph_inode_info,
 				      i_cap_delay_list);
 		list_del_init(&ci->i_cap_delay_list);

 		inode = igrab(&ci->netfs.inode);
 		if (inode) {
-			spin_unlock(&mdsc->cap_unlink_delay_lock);
+			spin_unlock(&mdsc->cap_delay_lock);
 			doutc(cl, "on %p %llx.%llx\n", inode,
 			      ceph_vinop(inode));
 			ceph_check_caps(ci, CHECK_CAPS_FLUSH);
 			iput(inode);
-			spin_lock(&mdsc->cap_unlink_delay_lock);
+			spin_lock(&mdsc->cap_delay_lock);
 		}
 	}
-	spin_unlock(&mdsc->cap_unlink_delay_lock);
+	spin_unlock(&mdsc->cap_delay_lock);
 	doutc(cl, "done\n");
 }


 int ceph_mdsc_init(struct ceph_fs_client *fsc)

 {
 	struct ceph_mds_client *mdsc;
 	int err;

 	mdsc = kzalloc(sizeof(struct ceph_mds_client), GFP_NOFS);
 	if (!mdsc)
 		return -ENOMEM;
 	mdsc->fsc = fsc;
 	mutex_init(&mdsc->mutex);
 	mdsc->mdsmap = kzalloc(sizeof(*mdsc->mdsmap), GFP_NOFS);
 	if (!mdsc->mdsmap) {
 		err = -ENOMEM;
 		goto err_mdsc;
 	}

